118	namespace {
119	void flushWrDiskCache(WrDiskCache* wrDiskCache,
120	                      const std::shared_ptr<Piece>& piece)
121	{
122	  piece->flushWrCache(wrDiskCache);
123	  if (piece->getWrDiskCacheEntry()->getError() !=
124	      WrDiskCacheEntry::CACHE_ERR_SUCCESS) {
125	    piece->clearAllBlock(wrDiskCache);
126	    throw DOWNLOAD_FAILURE_EXCEPTION2(
127	        fmt("Write disk cache flush failure index=%lu",
128	            static_cast<unsigned long>(piece->getIndex())),
129	        piece->getWrDiskCacheEntry()->getErrorCode());
130	  }
131	}
132	} // namespace
133	
134	std::shared_ptr<Segment>
135	SegmentMan::checkoutSegment(cuid_t cuid, const std::shared_ptr<Piece>& piece)
136	{
137	  if (!piece) {
138	    return nullptr;
139	  }
140	  A2_LOG_DEBUG(fmt("Attach segment#%lu to CUID#%" PRId64 ".",
141	                   static_cast<unsigned long>(piece->getIndex()), cuid));
142	
143	  if (piece->getWrDiskCacheEntry()) {
144	    // Flush cached data here, because the cached data may be overlapped
145	    // if BT peers are involved.
146	    A2_LOG_DEBUG(fmt(
147	        "Flushing cached data, size=%lu",
148	        static_cast<unsigned long>(piece->getWrDiskCacheEntry()->getSize())));
149	    flushWrDiskCache(pieceStorage_->getWrDiskCache(), piece);
150	  }
151	
152	  piece->setUsedBySegment(true);
153	  std::shared_ptr<Segment> segment;
154	  if (piece->getLength() == 0) {
155	    segment = std::make_shared<GrowSegment>(piece);
156	  }
157	  else {
158	    segment = std::make_shared<PiecedSegment>(
159	        downloadContext_->getPieceLength(), piece);
160	  }
161	  auto entry = std::make_shared<SegmentEntry>(cuid, segment);
162	  usedSegmentEntries_.push_back(entry);
163	  A2_LOG_DEBUG(fmt("index=%lu, length=%" PRId64 ", segmentLength=%" PRId64 ","
164	                   " writtenLength=%" PRId64,
165	                   static_cast<unsigned long>(segment->getIndex()),
166	                   segment->getLength(), segment->getSegmentLength(),
167	                   segment->getWrittenLength()));
168	
169	  if (piece->getLength() > 0) {
170	    auto positr = segmentWrittenLengthMemo_.find(segment->getIndex());
171	    if (positr != segmentWrittenLengthMemo_.end()) {
172	      const auto writtenLength = (*positr).second;
173	      A2_LOG_DEBUG(fmt("writtenLength(in memo)=%" PRId64
174	                       ", writtenLength=%" PRId64,
175	                       writtenLength, segment->getWrittenLength()));
176	      //  If the difference between cached writtenLength and segment's
177	      //  writtenLength is less than one block, we assume that these
178	      //  missing bytes are already downloaded.
179	      if (segment->getWrittenLength() < writtenLength &&
180	          writtenLength - segment->getWrittenLength() <
181	              piece->getBlockLength()) {
182	        segment->updateWrittenLength(writtenLength -
183	                                     segment->getWrittenLength());
184	      }
185	    }
186	  }
187	  return segment;
188	}
