190	void SegmentMan::getInFlightSegment(
191	    std::vector<std::shared_ptr<Segment>>& segments, cuid_t cuid)
192	{
193	  for (SegmentEntries::const_iterator itr = usedSegmentEntries_.begin(),
194	                                      eoi = usedSegmentEntries_.end();
195	       itr != eoi; ++itr) {
196	    const std::shared_ptr<SegmentEntry>& segmentEntry = *itr;
197	    if (segmentEntry->cuid == cuid) {
198	      segments.push_back(segmentEntry->segment);
199	    }
200	  }
201	}
