203	std::shared_ptr<Segment> SegmentMan::getSegment(cuid_t cuid,
204	                                                size_t minSplitSize)
205	{
206	  std::shared_ptr<Piece> piece = pieceStorage_->getMissingPiece(
207	      minSplitSize, ignoreBitfield_.getFilterBitfield(),
208	      ignoreBitfield_.getBitfieldLength(), cuid);
209	  return checkoutSegment(cuid, piece);
210	}
211	
212	void SegmentMan::getSegment(std::vector<std::shared_ptr<Segment>>& segments,
213	                            cuid_t cuid, size_t minSplitSize,
214	                            const std::shared_ptr<FileEntry>& fileEntry,
215	                            size_t maxSegments)
216	{
217	  BitfieldMan filter(ignoreBitfield_);
218	  filter.enableFilter();
219	  filter.addNotFilter(fileEntry->getOffset(), fileEntry->getLength());
220	  std::vector<std::shared_ptr<Segment>> pending;
221	  while (segments.size() < maxSegments) {
222	    std::shared_ptr<Segment> segment = checkoutSegment(
223	        cuid,
224	        pieceStorage_->getMissingPiece(minSplitSize, filter.getFilterBitfield(),
225	                                       filter.getBitfieldLength(), cuid));
226	    if (!segment) {
227	      break;
228	    }
229	    if (segment->getPositionToWrite() < fileEntry->getOffset() ||
230	        fileEntry->getLastOffset() <= segment->getPositionToWrite()) {
231	      pending.push_back(segment);
232	    }
233	    else {
234	      segments.push_back(segment);
235	    }
236	  }
237	  for (std::vector<std::shared_ptr<Segment>>::const_iterator
238	           i = pending.begin(),
239	           eoi = pending.end();
240	       i != eoi; ++i) {
241	    cancelSegment(cuid, *i);
242	  }
243	}
244	
245	std::shared_ptr<Segment> SegmentMan::getSegmentWithIndex(cuid_t cuid,
246	                                                         size_t index)
247	{
248	  if (index > 0 && downloadContext_->getNumPieces() <= index) {
249	    return nullptr;
250	  }
251	  return checkoutSegment(cuid, pieceStorage_->getMissingPiece(index, cuid));
252	}
253	
254	std::shared_ptr<Segment> SegmentMan::getCleanSegmentIfOwnerIsIdle(cuid_t cuid,
255	                                                                  size_t index)
256	{
257	  if (index > 0 && downloadContext_->getNumPieces() <= index) {
258	    return nullptr;
259	  }
260	  for (SegmentEntries::const_iterator itr = usedSegmentEntries_.begin(),
261	                                      eoi = usedSegmentEntries_.end();
262	       itr != eoi; ++itr) {
263	    const std::shared_ptr<SegmentEntry>& segmentEntry = *itr;
264	    if (segmentEntry->segment->getIndex() == index) {
265	      if (segmentEntry->segment->getWrittenLength() > 0) {
266	        return nullptr;
267	      }
268	      if (segmentEntry->cuid == cuid) {
269	        return segmentEntry->segment;
270	      }
271	      cuid_t owner = segmentEntry->cuid;
272	      std::shared_ptr<PeerStat> ps = getPeerStat(owner);
273	      if (!ps || ps->getStatus() == NetStat::IDLE) {
274	        cancelSegment(owner);
275	        return getSegmentWithIndex(cuid, index);
276	      }
277	      else {
278	        return nullptr;
279	      }
280	    }
281	  }
282	  return nullptr;
283	}
284	
285	void SegmentMan::cancelSegmentInternal(cuid_t cuid,
286	                                       const std::shared_ptr<Segment>& segment)
287	{
288	  A2_LOG_DEBUG(fmt("Canceling segment#%lu",
289	                   static_cast<unsigned long>(segment->getIndex())));
290	  const std::shared_ptr<Piece>& piece = segment->getPiece();
291	  // TODO In PieceStorage::cancelPiece(), WrDiskCacheEntry may be
292	  // released. Flush first.
293	  if (piece->getWrDiskCacheEntry()) {
294	    // Flush cached data here, because the cached data may be overlapped
295	    // if BT peers are involved.
296	    A2_LOG_DEBUG(fmt(
297	        "Flushing cached data, size=%lu",
298	        static_cast<unsigned long>(piece->getWrDiskCacheEntry()->getSize())));
299	    flushWrDiskCache(pieceStorage_->getWrDiskCache(), piece);
300	    // TODO Exception may cause some segments (pieces) are not
301	    // canceled.
302	  }
303	  piece->setUsedBySegment(false);
304	  pieceStorage_->cancelPiece(piece, cuid);
305	  segmentWrittenLengthMemo_[segment->getIndex()] = segment->getWrittenLength();
306	  A2_LOG_DEBUG(fmt("Memorized segment index=%lu, writtenLength=%" PRId64,
307	                   static_cast<unsigned long>(segment->getIndex()),
308	                   segment->getWrittenLength()));
309	}
310	
311	void SegmentMan::cancelSegment(cuid_t cuid)
312	{
313	  for (auto itr = usedSegmentEntries_.begin(), eoi = usedSegmentEntries_.end();
314	       itr != eoi;) {
315	    if ((*itr)->cuid == cuid) {
316	      cancelSegmentInternal(cuid, (*itr)->segment);
317	      itr = usedSegmentEntries_.erase(itr);
318	      eoi = usedSegmentEntries_.end();
319	    }
320	    else {
321	      ++itr;
322	    }
323	  }
324	}
325	
326	void SegmentMan::cancelSegment(cuid_t cuid,
327	                               const std::shared_ptr<Segment>& segment)
328	{
329	  for (auto itr = usedSegmentEntries_.begin(), eoi = usedSegmentEntries_.end();
330	       itr != eoi;) {
331	    if ((*itr)->cuid == cuid && *(*itr)->segment == *segment) {
332	      cancelSegmentInternal(cuid, (*itr)->segment);
333	      itr = usedSegmentEntries_.erase(itr);
334	      break;
335	    }
336	    else {
337	      ++itr;
338	    }
339	  }
340	}
341	
342	void SegmentMan::cancelAllSegments()
343	{
344	  for (auto& e : usedSegmentEntries_) {
345	    cancelSegmentInternal(e->cuid, e->segment);
346	  }
347	  usedSegmentEntries_.clear();
348	}
349	
350	void SegmentMan::eraseSegmentWrittenLengthMemo()
351	{
352	  segmentWrittenLengthMemo_.clear();
353	}
