355	namespace {
356	class FindSegmentEntry {
357	private:
358	  std::shared_ptr<Segment> segment_;
359	
360	public:
361	  FindSegmentEntry(std::shared_ptr<Segment> segment)
362	      : segment_(std::move(segment))
363	  {
364	  }
365	
366	  bool operator()(const std::shared_ptr<SegmentEntry>& segmentEntry) const
367	  {
368	    return segmentEntry->segment->getIndex() == segment_->getIndex();
369	  }
370	};
371	} // namespace
372	
373	bool SegmentMan::completeSegment(cuid_t cuid,
374	                                 const std::shared_ptr<Segment>& segment)
375	{
376	  pieceStorage_->completePiece(segment->getPiece());
377	  pieceStorage_->advertisePiece(cuid, segment->getPiece()->getIndex(),
378	                                global::wallclock());
379	  auto itr = std::find_if(usedSegmentEntries_.begin(),
380	                          usedSegmentEntries_.end(), FindSegmentEntry(segment));
381	  if (itr == usedSegmentEntries_.end()) {
382	    return false;
383	  }
384	  else {
385	    usedSegmentEntries_.erase(itr);
386	    return true;
387	  }
388	}
389	
390	bool SegmentMan::hasSegment(size_t index) const
391	{
392	  return pieceStorage_->hasPiece(index);
393	}
