405	void SegmentMan::registerPeerStat(const std::shared_ptr<PeerStat>& peerStat)
406	{
407	  peerStats_.push_back(peerStat);
408	}
409	
410	std::shared_ptr<PeerStat> SegmentMan::getPeerStat(cuid_t cuid) const
411	{
412	  for (auto& e : peerStats_) {
413	    if (e->getCuid() == cuid) {
414	      return e;
415	    }
416	  }
417	  return nullptr;
418	}
