421	class PeerStatHostProtoEqual {
422	private:
423	  const std::shared_ptr<PeerStat>& peerStat_;
424	
425	public:
426	  PeerStatHostProtoEqual(const std::shared_ptr<PeerStat>& peerStat)
427	      : peerStat_(peerStat)
428	  {
429	  }
430	
431	  bool operator()(const std::shared_ptr<PeerStat>& p) const
432	  {
