138	    return nullptr;
139	  }
140	  A2_LOG_DEBUG(fmt("Attach segment#%lu to CUID#%" PRId64 ".",
141	                   static_cast<unsigned long>(piece->getIndex()), cuid));
142	
143	  if (piece->getWrDiskCacheEntry()) {
144	    // Flush cached data here, because the cached data may be overlapped
145	    // if BT peers are involved.
146	    A2_LOG_DEBUG(fmt(
147	        "Flushing cached data, size=%lu",
148	        static_cast<unsigned long>(piece->getWrDiskCacheEntry()->getSize())));
149	    flushWrDiskCache(pieceStorage_->getWrDiskCache(), piece);
150	  }
151	
152	  piece->setUsedBySegment(true);
153	  std::shared_ptr<Segment> segment;
154	  if (piece->getLength() == 0) {
155	    segment = std::make_shared<GrowSegment>(piece);
156	  }
157	  else {
158	    segment = std::make_shared<PiecedSegment>(
159	        downloadContext_->getPieceLength(), piece);
