161	  auto entry = std::make_shared<SegmentEntry>(cuid, segment);
162	  usedSegmentEntries_.push_back(entry);
163	  A2_LOG_DEBUG(fmt("index=%lu, length=%" PRId64 ", segmentLength=%" PRId64 ","
164	                   " writtenLength=%" PRId64,
165	                   static_cast<unsigned long>(segment->getIndex()),
166	                   segment->getLength(), segment->getSegmentLength(),
167	                   segment->getWrittenLength()));
168	
169	  if (piece->getLength() > 0) {
170	    auto positr = segmentWrittenLengthMemo_.find(segment->getIndex());
171	    if (positr != segmentWrittenLengthMemo_.end()) {
172	      const auto writtenLength = (*positr).second;
173	      A2_LOG_DEBUG(fmt("writtenLength(in memo)=%" PRId64
174	                       ", writtenLength=%" PRId64,
175	                       writtenLength, segment->getWrittenLength()));
176	      //  If the difference between cached writtenLength and segment's
177	      //  writtenLength is less than one block, we assume that these
178	      //  missing bytes are already downloaded.
179	      if (segment->getWrittenLength() < writtenLength &&
180	          writtenLength - segment->getWrittenLength() <
181	              piece->getBlockLength()) {
182	        segment->updateWrittenLength(writtenLength -
183	                                     segment->getWrittenLength());
