212	void SegmentMan::getSegment(std::vector<std::shared_ptr<Segment>>& segments,
213	                            cuid_t cuid, size_t minSplitSize,
214	                            const std::shared_ptr<FileEntry>& fileEntry,
215	                            size_t maxSegments)
216	{
217	  BitfieldMan filter(ignoreBitfield_);
218	  filter.enableFilter();
219	  filter.addNotFilter(fileEntry->getOffset(), fileEntry->getLength());
220	  std::vector<std::shared_ptr<Segment>> pending;
221	  while (segments.size() < maxSegments) {
222	    std::shared_ptr<Segment> segment = checkoutSegment(
223	        cuid,
224	        pieceStorage_->getMissingPiece(minSplitSize, filter.getFilterBitfield(),
225	                                       filter.getBitfieldLength(), cuid));
226	    if (!segment) {
227	      break;
228	    }
229	    if (segment->getPositionToWrite() < fileEntry->getOffset() ||
230	        fileEntry->getLastOffset() <= segment->getPositionToWrite()) {
231	      pending.push_back(segment);
232	    }
233	    else {
234	      segments.push_back(segment);
235	    }
236	  }
237	  for (std::vector<std::shared_ptr<Segment>>::const_iterator
238	           i = pending.begin(),
239	           eoi = pending.end();
240	       i != eoi; ++i) {
241	    cancelSegment(cuid, *i);
242	  }
243	}
