439	void SegmentMan::updateFastestPeerStat(
440	    const std::shared_ptr<PeerStat>& peerStat)
441	{
442	  auto i = std::find_if(fastestPeerStats_.begin(), fastestPeerStats_.end(),
443	                        PeerStatHostProtoEqual(peerStat));
444	  if (i == fastestPeerStats_.end()) {
445	    fastestPeerStats_.push_back(peerStat);
446	  }
447	  else if ((*i)->getAvgDownloadSpeed() < peerStat->getAvgDownloadSpeed()) {
448	    // *i's SessionDownloadLength must be added to peerStat
449	    peerStat->addSessionDownloadLength((*i)->getSessionDownloadLength());
450	    *i = peerStat;
451	  }
452	  else {
453	    // peerStat's SessionDownloadLength must be added to *i
454	    (*i)->addSessionDownloadLength(peerStat->getSessionDownloadLength());
455	  }
