309	        index, minSplitSize,
310	        array(ignoreBitfield) | ~array(filterBitfield_) | array(bitfield_) |
311	            array(useBitfield_),
312	        useBitfield_, blockLength_, blocks_);
313	  }
314	  else {
315	    return aria2::getSparseMissingUnusedIndex(
