561	bool BitfieldMan::setBitInternal(unsigned char* bitfield, size_t index, bool on)
562	{
563	  if (blocks_ <= index) {
564	    return false;
565	  }
566	  unsigned char mask = 128 >> (index % 8);
567	  if (on) {
568	    bitfield[index / 8] |= mask;
569	  }
570	  else {
571	    bitfield[index / 8] &= ~mask;
572	  }
573	  return true;
574	}
