697	    setBitInternal(useBitfield_, i, true);
698	  }
699	}
700	
701	bool BitfieldMan::setFilterBit(size_t index)
702	{
703	  return setBitInternal(filterBitfield_, index, true);
704	}
705	
706	void BitfieldMan::ensureFilterBitfield()
707	{
708	  if (!filterBitfield_) {
709	    filterBitfield_ = new unsigned char[bitfieldLength_];
710	    std::fill_n(filterBitfield_, bitfieldLength_, 0);
711	  }
712	}
713	
714	void BitfieldMan::addFilter(int64_t offset, int64_t length)
715	{
716	  ensureFilterBitfield();
717	  if (length > 0) {
718	    size_t startBlock = offset / blockLength_;
719	    size_t endBlock = (offset + length - 1) / blockLength_;
720	    for (size_t i = startBlock; i <= endBlock && i < blocks_; i++) {
721	      setFilterBit(i);
722	    }
723	  }
724	  updateCache();
725	}
726	
727	void BitfieldMan::removeFilter(int64_t offset, int64_t length)
728	{
729	  ensureFilterBitfield();
730	  if (length > 0) {
731	    size_t startBlock = offset / blockLength_;
732	    size_t endBlock = (offset + length - 1) / blockLength_;
733	    for (size_t i = startBlock; i <= endBlock && i < blocks_; i++) {
734	      setBitInternal(filterBitfield_, i, false);
735	    }
736	  }
737	  updateCache();
738	}
739	
740	void BitfieldMan::addNotFilter(int64_t offset, int64_t length)
741	{
742	  ensureFilterBitfield();
743	  if (length > 0 && blocks_ > 0) {
744	    size_t startBlock = offset / blockLength_;
745	    if (blocks_ <= startBlock) {
746	      startBlock = blocks_;
747	    }
748	    size_t endBlock = (offset + length - 1) / blockLength_;
749	    for (size_t i = 0; i < startBlock; ++i) {
750	      setFilterBit(i);
751	    }
752	    for (size_t i = endBlock + 1; i < blocks_; ++i) {
753	      setFilterBit(i);
754	    }
755	  }
756	  updateCache();
757	}
758	
759	void BitfieldMan::enableFilter()
760	{
761	  ensureFilterBitfield();
762	  filterEnabled_ = true;
763	  updateCache();
764	}
765	
766	void BitfieldMan::disableFilter()
767	{
768	  filterEnabled_ = false;
769	  updateCache();
770	}
771	
772	void BitfieldMan::clearFilter()
773	{
774	  if (filterBitfield_) {
775	    delete[] filterBitfield_;
776	    filterBitfield_ = nullptr;
777	  }
778	  filterEnabled_ = false;
779	  updateCache();
780	}
781	
782	int64_t BitfieldMan::getFilteredTotalLengthNow() const
783	{
784	  if (!filterBitfield_) {
785	    return 0;
786	  }
787	  size_t filteredBlocks = bitfield::countSetBit(filterBitfield_, blocks_);
788	  if (filteredBlocks == 0) {
789	    return 0;
790	  }
791	  if (bitfield::test(filterBitfield_, blocks_, blocks_ - 1)) {
792	    return ((int64_t)filteredBlocks - 1) * blockLength_ + getLastBlockLength();
793	  }
794	  else {
795	    return ((int64_t)filteredBlocks) * blockLength_;
796	  }
797	}
798	
799	namespace {
800	template <typename Array, typename CountFun>
801	int64_t computeCompletedLength(const Array& bitfield, const BitfieldMan* btman,
802	                               CountFun cntfun)
803	{
804	  size_t nbits = btman->countBlock();
805	  size_t completedBlocks = cntfun(bitfield, nbits);
806	  int64_t completedLength = 0;
807	  if (completedBlocks == 0) {
808	    completedLength = 0;
809	  }
810	  else {
811	    if (bitfield::test(bitfield, nbits, nbits - 1)) {
812	      completedLength =
813	          ((int64_t)completedBlocks - 1) * btman->getBlockLength() +
814	          btman->getLastBlockLength();
815	    }
816	    else {
817	      completedLength = ((int64_t)completedBlocks) * btman->getBlockLength();
818	    }
819	  }
820	  return completedLength;
821	}
822	} // namespace
823	
824	int64_t BitfieldMan::getCompletedLength(bool useFilter) const
825	{
826	  if (useFilter && filterEnabled_) {
827	    auto arr = array(bitfield_) & array(filterBitfield_);
828	    return computeCompletedLength(arr, this,
829	                                  &bitfield::countSetBitSlow<decltype(arr)>);
830	  }
831	  else {
832	    return computeCompletedLength(bitfield_, this, &bitfield::countSetBit);
833	  }
834	}
835	
836	int64_t BitfieldMan::getCompletedLengthNow() const
837	{
838	  return getCompletedLength(false);
839	}
840	
841	int64_t BitfieldMan::getFilteredCompletedLengthNow() const
842	{
843	  return getCompletedLength(true);
844	}
845	
846	void BitfieldMan::updateCache()
847	{
848	  cachedNumMissingBlock_ = countMissingBlockNow();
849	  cachedNumFilteredBlock_ = countFilteredBlockNow();
850	  cachedFilteredTotalLength_ = getFilteredTotalLengthNow();
851	  cachedCompletedLength_ = getCompletedLengthNow();
852	  cachedFilteredCompletedLength_ = getFilteredCompletedLengthNow();
853	}
854	
855	bool BitfieldMan::isBitRangeSet(size_t startIndex, size_t endIndex) const
856	{
857	  for (size_t i = startIndex; i <= endIndex; ++i) {
858	    if (!isBitSet(i)) {
859	      return false;
860	    }
861	  }
862	  return true;
863	}
864	
865	void BitfieldMan::unsetBitRange(size_t startIndex, size_t endIndex)
866	{
867	  for (size_t i = startIndex; i <= endIndex; ++i) {
868	    unsetBit(i);
869	  }
870	  updateCache();
871	}
872	
873	void BitfieldMan::setBitRange(size_t startIndex, size_t endIndex)
874	{
875	  for (size_t i = startIndex; i <= endIndex; ++i) {
876	    setBit(i);
877	  }
878	  updateCache();
879	}
880	
881	bool BitfieldMan::isBitSetOffsetRange(int64_t offset, int64_t length) const
882	{
883	  if (length <= 0) {
884	    return false;
885	  }
886	  if (totalLength_ <= offset) {
887	    return false;
888	  }
889	  if (totalLength_ < offset + length) {
890	    length = totalLength_ - offset;
891	  }
892	  size_t startBlock = offset / blockLength_;
893	  size_t endBlock = (offset + length - 1) / blockLength_;
894	  for (size_t i = startBlock; i <= endBlock; i++) {
895	    if (!isBitSet(i)) {
896	      return false;
897	    }
898	  }
899	  return true;
900	}
901	
902	int64_t BitfieldMan::getOffsetCompletedLength(int64_t offset,
903	                                              int64_t length) const
904	{
905	  int64_t res = 0;
906	  if (length == 0 || totalLength_ <= offset) {
907	    return 0;
908	  }
909	  if (totalLength_ < offset + length) {
910	    length = totalLength_ - offset;
911	  }
912	  size_t start = offset / blockLength_;
913	  size_t end = (offset + length - 1) / blockLength_;
914	  if (start == end) {
915	    if (isBitSet(start)) {
916	      res = length;
917	    }
918	  }
919	  else {
920	    if (isBitSet(start)) {
921	      res += static_cast<int64_t>(start + 1) * blockLength_ - offset;
922	    }
923	    for (size_t i = start + 1; i <= end - 1; ++i) {
924	      if (isBitSet(i)) {
925	        res += blockLength_;
926	      }
927	    }
928	    if (isBitSet(end)) {
929	      res += offset + length - static_cast<int64_t>(end) * blockLength_;
930	    }
931	  }
932	  return res;
933	}
934	
935	int64_t BitfieldMan::getMissingUnusedLength(size_t startingIndex) const
936	{
937	  if (blocks_ <= startingIndex) {
938	    return 0;
939	  }
940	  int64_t length = 0;
941	  for (size_t i = startingIndex; i < blocks_; ++i) {
942	    if (isBitSet(i) || isUseBitSet(i)) {
943	      break;
944	    }
945	    length += getBlockLength(i);
946	  }
947	  return length;
948	}
949	
950	BitfieldMan::Range::Range(size_t startIndex, size_t endIndex)
951	    : startIndex(startIndex), endIndex(endIndex)
952	{
953	}
954	
955	size_t BitfieldMan::Range::getSize() const { return endIndex - startIndex; }
956	
957	size_t BitfieldMan::Range::getMidIndex() const
958	{
959	  return (endIndex - startIndex) / 2 + startIndex;
960	}
961	
962	bool BitfieldMan::Range::operator<(const Range& range) const
963	{
964	  return getSize() < range.getSize();
965	}
966	
967	bool BitfieldMan::Range::operator==(const Range& range) const
968	{
969	  return getSize() == range.getSize();
970	}
971	
972	} // namespace aria2
