42	                             const std::shared_ptr<Piece>& piece)
43	    : piece_(piece), pieceLength_(pieceLength)
44	{
45	  size_t index;
46	  bool t = piece_->getFirstMissingBlockIndexWithoutLock(index);
47	  assert(t);
48	  writtenLength_ = index * piece_->getBlockLength();
49	}
