68	
69	void PiecedSegment::updateWrittenLength(int64_t bytes)
70	{
71	  auto newWrittenLength = writtenLength_ + bytes;
72	  assert(newWrittenLength <= piece_->getLength());
73	  for (auto i = writtenLength_ / piece_->getBlockLength(),
74	            end = newWrittenLength / piece_->getBlockLength();
75	       i < end; ++i) {
76	    piece_->completeBlock(i);
77	  }
78	  if (newWrittenLength == piece_->getLength()) {
79	    piece_->completeBlock(piece_->countBlock() - 1);
80	  }
81	  writtenLength_ = newWrittenLength;
82	}
