87	void ServerStat::updateSingleConnectionAvgSpeed(int downloadSpeed)
88	{
89	  float avgDownloadSpeed;
90	  if (counter_ == 0)
91	    return;
92	  if (counter_ < 5) {
93	    avgDownloadSpeed = ((((float)counter_ - 1) / (float)counter_) *
94	                        (float)singleConnectionAvgSpeed_) +
95	                       ((1.0 / (float)counter_) * (float)downloadSpeed);
96	  }
97	  else {
98	    avgDownloadSpeed = ((4.0 / 5.0) * (float)singleConnectionAvgSpeed_) +
99	                       ((1.0 / 5.0) * (float)downloadSpeed);
100	  }
101	  if (avgDownloadSpeed < (int)(0.80 * singleConnectionAvgSpeed_)) {
102	    A2_LOG_DEBUG(fmt("ServerStat:%s: resetting counter since single connection"
103	                     " speed dropped",
104	                     getHostname().c_str()));
105	    counter_ = 0;
106	  }
107	  A2_LOG_DEBUG(
108	      fmt("ServerStat:%s: singleConnectionAvgSpeed_ old:%.2fKB/s"
109	          " new:%.2fKB/s last:%.2fKB/s",
110	          getHostname().c_str(), (float)singleConnectionAvgSpeed_ / 1024,
111	          (float)avgDownloadSpeed / 1024, (float)downloadSpeed / 1024));
112	  singleConnectionAvgSpeed_ = (int)avgDownloadSpeed;
113	}
