126	    avgDownloadSpeed = ((((float)counter_ - 1) / (float)counter_) *
127	                        (float)multiConnectionAvgSpeed_) +
128	                       ((1.0 / (float)counter_) * (float)downloadSpeed);
129	  }
130	  else {
131	    avgDownloadSpeed = ((4.0 / 5.0) * (float)multiConnectionAvgSpeed_) +
132	                       ((1.0 / 5.0) * (float)downloadSpeed);
133	  }
134	  A2_LOG_DEBUG(
135	      fmt("ServerStat:%s: multiConnectionAvgSpeed_ old:%.2fKB/s"
136	          " new:%.2fKB/s last:%.2fKB/s",
137	          getHostname().c_str(), (float)multiConnectionAvgSpeed_ / 1024,
138	          (float)avgDownloadSpeed / 1024, (float)downloadSpeed / 1024));
139	  multiConnectionAvgSpeed_ = (int)avgDownloadSpeed;
140	}
